# ==============================================================================# 100_REVENUE_ENGINE.py## IOTEC REVENUE ENGINE## Missão:# Reconhecer receitas provenientes de cobranças pagas.# ==============================================================================from __future__ import annotationsimport sqlite3import uuidimport hashlibimport jsonfrom pathlib import Pathfrom datetime import datetimeDB = Path("iotec.db")class RevenueEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS commercial_revenues(            id INTEGER PRIMARY KEY AUTOINCREMENT,            revenue_uuid TEXT UNIQUE,            billing_uuid TEXT UNIQUE,            contract_uuid TEXT,            company_uuid TEXT,            amount REAL,            currency TEXT,            recognized_at TEXT,            payment_method TEXT,            status TEXT,            metadata TEXT,            hash TEXT        )        """)        self.conn.commit()    # ------------------------------------------------------------------    def _sha(self, obj):        raw = json.dumps(            obj,            ensure_ascii=False,            sort_keys=True        )        return hashlib.sha256(raw.encode()).hexdigest()    # ------------------------------------------------------------------    def recognize_revenue(self, billing_uuid):        billing = self.conn.execute("""            SELECT                b.*,                c.company_uuid            FROM commercial_billings b            JOIN commercial_contracts c                 ON c.contract_uuid = b.contract_uuid            WHERE b.billing_uuid=?            LIMIT 1        """, (billing_uuid,)).fetchone()        if billing is None:            raise RuntimeError("Cobrança não encontrada.")        if billing["status"] != "PAID":            raise RuntimeError(                "Receita não pode ser reconhecida. "                "A cobrança ainda não está paga."            )        existe = self.conn.execute("""            SELECT 1            FROM commercial_revenues            WHERE billing_uuid=?        """, (billing_uuid,)).fetchone()        if existe:            raise RuntimeError(                "Esta receita já foi reconhecida."            )        payload = {            "revenue_uuid": str(uuid.uuid4()),            "billing_uuid": billing["billing_uuid"],            "contract_uuid": billing["contract_uuid"],            "company_uuid": billing["company_uuid"],            "amount": billing["amount"],            "currency": billing["currency"],            "recognized_at": datetime.utcnow().isoformat(),            "payment_method": billing["payment_method"],            "status": "RECOGNIZED",            "metadata": {                "origin":"100_REVENUE_ENGINE"            }        }        assinatura = self._sha(payload)        self.conn.execute("""        INSERT INTO commercial_revenues(            revenue_uuid,            billing_uuid,            contract_uuid,            company_uuid,            amount,            currency,            recognized_at,            payment_method,            status,            metadata,            hash        )        VALUES(?,?,?,?,?,?,?,?,?,?,?)        """,(            payload["revenue_uuid"],            payload["billing_uuid"],            payload["contract_uuid"],            payload["company_uuid"],            payload["amount"],            payload["currency"],            payload["recognized_at"],            payload["payment_method"],            payload["status"],            json.dumps(payload["metadata"], ensure_ascii=False),            assinatura        ))        self.conn.commit()        payload["hash"] = assinatura        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    conn = sqlite3.connect(DB)    conn.row_factory = sqlite3.Row    billing = conn.execute("""        SELECT billing_uuid        FROM commercial_billings        LIMIT 1    """).fetchone()    if billing is None:        raise RuntimeError("Nenhuma cobrança encontrada.")    engine = RevenueEngine()    resultado = engine.recognize_revenue(        billing["billing_uuid"]    )    print("="*80)    print("REVENUE ENGINE")    print("="*80)    for k, v in resultado.items():        print(f"{k:20}: {v}")    print("="*80)